css:
.c6-vertical-text {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 1.8rem;
  font-weight: 600;
  white-space: nowrap;
  color: white;
  text-transform: capitalize;
  padding: 20px 10px;
  position: relative;
  background: linear-gradient(to top, transparent 50%, #1C1D2D 50%);
  border-radius: 0;
}
